/* Mobile menu accordion (the panel opened by the header hamburger).
   The drawer behaviour already opens and closes the panel, locks page scroll and handles Escape;
   this only adds the + / - button on each top-level row and keeps one row open at a time.
   Until it runs the panel simply lists every link, so nothing is hidden without a script. */
(function () {
  'use strict';
  var uid = 0;

  function isPlaceholder(a) {
    var h = (a.getAttribute('href') || '').trim();
    return h === '' || h === '#' || h === '/#';
  }

  function setup(nav) {
    if (nav.classList.contains('is-acc')) return;
    var rows = [].filter.call(nav.children, function (li) {
      return li.classList.contains('bz-navitem--has-sub');
    });
    if (!rows.length) return;

    function toggle(li, open) {
      rows.forEach(function (other) {
        var on = other === li && open;
        other.classList.toggle('is-open', on);
        var b = other.querySelector(':scope > .bz-acc');
        if (b) b.setAttribute('aria-expanded', String(on));
      });
    }

    rows.forEach(function (li) {
      var sub = li.querySelector(':scope > .bz-subnav');
      var head = li.querySelector(':scope > a, :scope > .bz-navlabel');
      if (!sub || !head) return;
      uid += 1;
      sub.id = sub.id || 'bz-acc-' + uid;
      var btn = document.createElement('button');
      btn.type = 'button';
      btn.className = 'bz-acc';
      btn.setAttribute('aria-expanded', 'false');
      btn.setAttribute('aria-controls', sub.id);
      btn.setAttribute('aria-label', head.textContent.trim() + ' submenu');
      btn.addEventListener('click', function () {
        toggle(li, !li.classList.contains('is-open'));
      });
      li.insertBefore(btn, sub);
      // A heading that goes nowhere (a label, or a "#" placeholder link) opens the row too.
      if (head.tagName !== 'A' || isPlaceholder(head)) {
        head.addEventListener('click', function (e) {
          e.preventDefault();
          toggle(li, !li.classList.contains('is-open'));
        });
      }
    });

    nav.classList.add('is-acc');

    // Closing the panel resets it, so it reopens with every row folded.
    var header = nav.closest('[data-bz-node="hdr"]');
    if (header && window.MutationObserver) {
      new MutationObserver(function () {
        if (!header.hasAttribute('data-open')) toggle(null, false);
      }).observe(header, { attributes: true, attributeFilter: ['data-open'] });
    }
  }

  function init() {
    [].forEach.call(document.querySelectorAll('[data-bz-node="pnl-menu"] .bz-nav'), setup);
  }

  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init);
  else init();
})();
